<script>
    // Initialize Lucide icons
    lucide.createIcons();

    // Global Toast Notification System
    function showToast(message, type = 'success') {
        let toastContainer = document.getElementById('toast-container');
        if (!toastContainer) {
            toastContainer = document.createElement('div');
            toastContainer.id = 'toast-container';
            toastContainer.style.cssText = 'position: fixed; top: 20px; left: 50%; transform: translateX(-50%); z-index: 9999; display: flex; flex-direction: column; gap: 10px; pointer-events: none;';
            document.body.appendChild(toastContainer);
        }

        const toast = document.createElement('div');
        const bgColor = type === 'error' ? '#fef2f2' : '#f0fdf4';
        const borderColor = type === 'error' ? '#fecaca' : '#bbf7d0';
        const iconColor = type === 'error' ? '#ef4444' : '#22c55e';
        const iconSvg = type === 'error' 
            ? '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="15" y1="9" x2="9" y2="15"></line><line x1="9" y1="9" x2="15" y2="15"></line></svg>'
            : '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path><polyline points="22 4 12 14.01 9 11.01"></polyline></svg>';

        toast.style.cssText = `
            background: ${bgColor}; 
            border: 1px solid ${borderColor}; 
            color: #3d3551; 
            padding: 12px 20px; 
            border-radius: 50px; 
            font-size: 14px; 
            font-weight: 600; 
            display: flex; 
            align-items: center; 
            gap: 10px; 
            box-shadow: 0 10px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);
            opacity: 0;
            transform: translateY(-20px);
            transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
        `;
        
        toast.innerHTML = `<span style="color: ${iconColor}; display: flex;">${iconSvg}</span> <span>${message}</span>`;
        toastContainer.appendChild(toast);

        // Animate in
        requestAnimationFrame(() => {
            toast.style.opacity = '1';
            toast.style.transform = 'translateY(0)';
        });

        // Animate out
        setTimeout(() => {
            toast.style.opacity = '0';
            toast.style.transform = 'translateY(-20px)';
            setTimeout(() => toast.remove(), 300);
        }, 3000);
    }
    
</script>
<script>
// Interactive Client-Side Search and Category Filtering
(function() {
    const searchInput = document.querySelector('.tm-search input[name="search"]');
    const categoryLinks = document.querySelectorAll('.tm-categories .tm-category');
    const cards = document.querySelectorAll('.tm-grid .tm-card');
    const resultCountStrong = document.querySelector('.tm-result-count strong');
    const heroStatsStrong = document.querySelector('.tm-hero__stats span:first-child strong');
    
    let currentCategory = 'all';
    let currentKeyword = '';

    // Check URL parameters on load
    const urlParams = new URLSearchParams(window.location.search);
    const catParam = urlParams.get('categoryId');
    const searchParam = urlParams.get('search');

    if (catParam) {
        currentCategory = catParam;
        categoryLinks.forEach(link => {
            const href = link.getAttribute('href') || '';
            if (href.includes('categoryId=' + catParam)) {
                categoryLinks.forEach(l => l.classList.remove('is-active'));
                link.classList.add('is-active');
            }
        });
    }

    if (searchParam) {
        currentKeyword = searchParam.trim().toLowerCase();
        if (searchInput) searchInput.value = searchParam;
    }

    function filterCards() {
        let visibleCount = 0;
        cards.forEach(card => {
            const cardCatId = card.getAttribute('data-category-id') || '';
            const cardText = (card.innerText || '').toLowerCase();
            
            const matchCategory = (currentCategory === 'all' || currentCategory === '' || cardCatId === currentCategory);
            const matchSearch = (!currentKeyword || cardText.includes(currentKeyword));
            
            if (matchCategory && matchSearch) {
                card.style.display = '';
                visibleCount++;
            } else {
                card.style.display = 'none';
            }
        });

        if (resultCountStrong) resultCountStrong.textContent = visibleCount;
        if (heroStatsStrong) heroStatsStrong.textContent = visibleCount;
    }

    // Category click handler
    categoryLinks.forEach(link => {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            categoryLinks.forEach(l => l.classList.remove('is-active'));
            this.classList.add('is-active');
            
            const href = this.getAttribute('href') || '';
            if (href.includes('categoryId=')) {
                currentCategory = href.split('categoryId=')[1].split('&')[0];
            } else {
                currentCategory = 'all';
            }
            
            // Update URL without reload
            const newUrl = currentCategory === 'all' ? 'templates.php' : 'templates.php?categoryId=' + currentCategory;
            window.history.pushState({ category: currentCategory }, '', newUrl);
            
            filterCards();
        });
    });

    // Real-time search handler
    if (searchInput) {
        searchInput.addEventListener('input', function() {
            currentKeyword = this.value.trim().toLowerCase();
            filterCards();
        });
        
        const searchForm = document.querySelector('.tm-search');
        if (searchForm) {
            searchForm.addEventListener('submit', function(e) {
                e.preventDefault();
                currentKeyword = searchInput.value.trim().toLowerCase();
                filterCards();
            });
        }
    }

    // Floating gift stage click opens voucher modal
    const giftStage = document.querySelector('.tm-gift-stage');
    if (giftStage) {
        giftStage.style.cursor = 'pointer';
        giftStage.addEventListener('click', function() {
            if (typeof openVoucherModal === 'function') {
                openVoucherModal();
            }
        });
    }

    // Run initial filter
    filterCards();
})();
</script>
<script id="dg-i18n-script">
(function() {
  const dict = {
    'Sản phẩm': 'Products',
    'Ý tưởng quà tặng': 'Gift Ideas',
    'Đánh giá': 'Reviews',
    'Về DearGift': 'About DearGift',
    'Đăng nhập': 'Sign in',
    'Đăng ký': 'Sign up',
    'Tạo tài khoản': 'Sign up',
    'Xem thử': 'Preview',
    'Tạo quà ngay': 'Create Gift',
    'Tất cả': 'All',
    'Sinh nhật': 'Birthday',
    'Tình yêu': 'Love',
    'Kỷ niệm': 'Anniversary',
    'Món Quà Nhỏ': 'Small Gift',
    'Bảng giá': 'Pricing',
    'Câu hỏi thường gặp': 'FAQ',
    'Liên hệ': 'Contact',
    'Gợi ý theo dịp': 'Occasion Ideas',
    'Cảm nhận người dùng': 'Testimonials',
    'Câu chuyện thương hiệu': 'Brand Story',
    'Hỗ trợ & góp ý': 'Support'
  };

  function applyLang(lang) {
    localStorage.setItem('deargift_lang', lang);
    const isEn = lang === 'en';

    // Update active class on switcher
    document.querySelectorAll('.dg-language-switch a, .auth-lang-switch a').forEach(el => {
      const elLang = el.getAttribute('lang') || el.innerText.trim().toLowerCase();
      if ((isEn && elLang.toLowerCase() === 'en') || (!isEn && elLang.toLowerCase() === 'vi')) {
        el.classList.add('is-active', 'active');
      } else {
        el.classList.remove('is-active', 'active');
      }
    });

    // Translate text nodes
    const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null, false);
    let node;
    while(node = walk.nextNode()) {
      const val = node.nodeValue.trim();
      if (!isEn) {
        // Revert reverse dictionary
        for (const [vi, en] of Object.entries(dict)) {
          if (val === en) {
            node.nodeValue = node.nodeValue.replace(en, vi);
            break;
          }
        }
      } else {
        for (const [vi, en] of Object.entries(dict)) {
          if (val === vi) {
            node.nodeValue = node.nodeValue.replace(vi, en);
            break;
          }
        }
      }
    }
  }

  // Intercept click on lang switch
  document.addEventListener('click', function(e) {
    const target = e.target.closest('.dg-language-switch a, .auth-lang-switch a');
    if (!target) return;
    const lang = target.getAttribute('lang') || target.innerText.trim().toLowerCase();
    if (lang === 'en' || lang === 'vi') {
      e.preventDefault();
      applyLang(lang);
      const url = new URL(window.location.href);
      url.searchParams.set('lang', lang);
      window.history.replaceState({}, '', url.toString());
    }
  });

  // Check on load
  const params = new URLSearchParams(window.location.search);
  const currentLang = params.get('lang') || localStorage.getItem('deargift_lang') || 'vi';
  if (currentLang === 'en') {
    window.addEventListener('DOMContentLoaded', () => applyLang('en'));
  }
})();

// Header User Auth Bar Sync
document.addEventListener('DOMContentLoaded', function() {
    try {
        function renderUserAuth(user) {
            var authDiv = document.getElementById('header-auth-buttons');
            if (user && authDiv) {
                var name = user.full_name || user.name || user.username || 'Khách';
                authDiv.innerHTML = `
                    <a href="my-gifts.php" class="btn-login hdr-desktop-only" style="background:#fce7f3; color:#e8589a; border:1px solid #fbcfe8; font-weight:700; text-decoration:none; padding:7px 14px; border-radius:50px;">🎁 Quà của tôi</a>
                    <div class="hdr-desktop-only" style="display:flex; align-items:center; gap:6px; font-size:13px; font-weight:700; color:#3d3551; background:#f5eeff; padding:6px 14px; border-radius:50px;">
                        <span>👤</span>
                        <a href="settings.php" style="color:#3d3551; text-decoration:none; font-weight:700;" title="Cài đặt & Bảo mật">${name}</a>
                        <a href="#" onclick="localStorage.removeItem('deargift_user');localStorage.removeItem('deargift_customer');document.cookie='currentUser=; path=/; max-age=0';location.reload();" style="color:#e8589a; margin-left:6px; font-size:11px; text-decoration:none;" title="Đăng xuất">Thoát</a>
                    </div>
                `;
                var mProfile = document.querySelector('.mnav-profile');
                var mAuth = document.querySelector('.mnav-auth');
                if (mProfile && mAuth) {
                    mProfile.className = 'mnav-profile';
                    mProfile.innerHTML = `
                        <span class="mnav-profile__avatar"><i data-lucide="user"></i></span>
                        <div class="mnav-profile__copy">
                            <strong>${name}</strong>
                            <span>${user.email || 'Tài khoản thành viên'}</span>
                        </div>
                    `;
                    mAuth.innerHTML = `
                        <a class="mnav-auth__login" href="my-gifts.php"><i data-lucide="gift"></i> Quà của tôi</a>
                        <a class="mnav-auth__register" href="settings.php"><i data-lucide="settings"></i> Cài đặt</a>
                    `;
                }
            }
        }

        var localUser = JSON.parse(localStorage.getItem('deargift_user') || localStorage.getItem('deargift_customer') || 'null');
        if (localUser) {
            renderUserAuth(localUser);
        } else {
            fetch('/api/me').then(r => r.json()).then(res => {
                if (res.status === 'success' && res.user) {
                    localStorage.setItem('deargift_user', JSON.stringify(res.user));
                    renderUserAuth(res.user);
                }
            }).catch(function(){});
        }
    } catch(e) {}
});
</script>

<script id="dg-category-filter-engine">
(function() {
    'use strict';

    function removeVietnameseTones(str) {
        if (!str) return '';
        str = str.toLowerCase();
        str = str.replace(/à|á|ạ|ả|ã|â|ầ|ấ|ậ|ẩ|ẫ|ă|ằ|ắ|ặ|ẳ|ẵ/g, "a");
        str = str.replace(/è|é|ẹ|ẻ|ẽ|ê|ề|ế|ệ|ể|ễ/g, "e");
        str = str.replace(/ì|í|ị|ỉ|ĩ/g, "i");
        str = str.replace(/ò|ó|ọ|ỏ|õ|ô|ồ|ố|ộ|ổ|ỗ|ơ|ờ|ớ|ợ|ở|ỡ/g, "o");
        str = str.replace(/ù|ú|ụ|ủ|ũ|ư|ừ|ứ|ự|ử|ữ/g, "u");
        str = str.replace(/ỳ|ý|ỵ|ỷ|ỹ/g, "y");
        str = str.replace(/đ/g, "d");
        str = str.replace(/\u0300|\u0301|\u0303|\u0309|\u0323/g, "");
        str = str.replace(/\u02C6|\u031B|\u0306/g, "");
        return str.trim();
    }

    var categoryNames = {
        '1': 'Tất cả mẫu quà',
        '2': 'Mẫu quà Valentine',
        '3': 'Mẫu quà Sinh nhật',
        '4': 'Mẫu quà Ngày Phụ Nữ',
        '5': 'Mẫu quà Ngày Nhà Giáo',
        '6': 'Mẫu quà Lễ hội & Kỷ niệm',
        '7': 'Mẫu quà Tết & Năm mới',
        '8': 'Mẫu quà Trải nghiệm 3D',
        '9': 'Mẫu quà Tình yêu',
        '10': 'Mẫu quà Mọi dịp'
    };

    function filterTemplates(catId, searchQuery) {
        catId = String(catId || '1');
        var qNorm = removeVietnameseTones(searchQuery || '');
        var cards = document.querySelectorAll('.tm-card');
        var visibleCount = 0;

        cards.forEach(function(card) {
            var cardCats = (card.getAttribute('data-category-ids') || '1').split(',');
            var matchCat = (catId === '1' || catId === 'all') ? true : cardCats.indexOf(catId) !== -1;

            var matchSearch = true;
            if (qNorm) {
                var cardText = removeVietnameseTones(card.innerText || '');
                matchSearch = cardText.indexOf(qNorm) !== -1;
            }

            if (matchCat && matchSearch) {
                card.style.display = '';
                visibleCount++;
            } else {
                card.style.display = 'none';
            }
        });

        // Update category tab active state
        document.querySelectorAll('.tm-category').forEach(function(btn) {
            var href = btn.getAttribute('href') || '';
            var m = href.match(/categoryId=(\d+)/);
            var btnCatId = m ? m[1] : '1';
            if (btnCatId === catId) {
                btn.classList.add('is-active');
            } else {
                btn.classList.remove('is-active');
            }
        });

        // Update section heading
        var headingTitle = document.querySelector('.tm-filter-head strong') || document.querySelector('.tm-section-head h2');
        if (headingTitle) {
            var catName = categoryNames[catId] || 'Bộ sưu tập mẫu quà';
            if (qNorm) {
                headingTitle.textContent = 'Kết quả tìm kiếm "' + searchQuery + '" (' + visibleCount + ')';
            } else {
                headingTitle.textContent = catName + ' (' + visibleCount + ')';
            }
        }

        // Handle empty state
        var container = document.querySelector('.tm-cards-grid') || document.querySelector('.tm-collection .container');
        var emptyEl = document.getElementById('tm-search-empty');
        if (visibleCount === 0) {
            if (!emptyEl && container) {
                emptyEl = document.createElement('div');
                emptyEl.id = 'tm-search-empty';
                emptyEl.style.cssText = 'text-align:center; padding:60px 20px; grid-column:1/-1; background:#fff; border-radius:20px; border:1px dashed #f0c0cc; margin:20px 0;';
                emptyEl.innerHTML = '<div style="font-size:48px; margin-bottom:12px;">🔍</div><h3 style="font-size:18px; font-weight:800; color:#3d3551; margin-bottom:6px;">Không tìm thấy mẫu quà phù hợp</h3><p style="font-size:13px; color:#7a7090; margin-bottom:18px;">Thử tìm kiếm với từ khóa khác như "sinh nhật", "valentine", "3d", "hoa", "galaxy"...</p><button type="button" onclick="resetFilter()" style="padding:10px 22px; border-radius:50px; background:linear-gradient(135deg,#e8589a,#e8589a); color:#fff; border:none; font-weight:700; font-size:13px; cursor:pointer;">Xem tất cả mẫu quà</button>';
                container.appendChild(emptyEl);
            }
            if (emptyEl) emptyEl.style.display = 'block';
        } else {
            if (emptyEl) emptyEl.style.display = 'none';
        }
    }

    window.resetFilter = function() {
        var inp = document.querySelector('input[name="search"]');
        if (inp) inp.value = '';
        filterTemplates('1', '');
        history.pushState(null, '', 'templates.php');
    };

    // Category click handler
    document.addEventListener('click', function(e) {
        var btn = e.target.closest('.tm-category');
        if (!btn) return;
        e.preventDefault();
        var href = btn.getAttribute('href') || '';
        var m = href.match(/categoryId=(\d+)/);
        var catId = m ? m[1] : '1';
        var searchInput = document.querySelector('input[name="search"]');
        var q = searchInput ? searchInput.value.trim() : '';

        filterTemplates(catId, q);

        var newUrl = catId === '1' ? 'templates.php' : ('templates.php?categoryId=' + catId);
        if (q) newUrl += (newUrl.indexOf('?') !== -1 ? '&' : '?') + 'search=' + encodeURIComponent(q);
        history.pushState(null, '', newUrl);
    });

    // Live search handler
    var searchTimer = null;
    document.addEventListener('input', function(e) {
        var inp = e.target.closest('input[name="search"]');
        if (!inp) return;
        clearTimeout(searchTimer);
        searchTimer = setTimeout(function() {
            var activeBtn = document.querySelector('.tm-category.is-active');
            var m = activeBtn ? (activeBtn.getAttribute('href') || '').match(/categoryId=(\d+)/) : null;
            var catId = m ? m[1] : '1';
            filterTemplates(catId, inp.value.trim());
        }, 150);
    });

    // Prevent search form reload
    var searchForm = document.querySelector('form.tm-search');
    if (searchForm) {
        searchForm.addEventListener('submit', function(e) {
            e.preventDefault();
            var inp = searchForm.querySelector('input[name="search"]');
            var q = inp ? inp.value.trim() : '';
            var activeBtn = document.querySelector('.tm-category.is-active');
            var m = activeBtn ? (activeBtn.getAttribute('href') || '').match(/categoryId=(\d+)/) : null;
            var catId = m ? m[1] : '1';
            filterTemplates(catId, q);
        });
    }

    // Run on load
    document.addEventListener('DOMContentLoaded', function() {
        var params = new URLSearchParams(window.location.search);
        var catId = params.get('categoryId') || '1';
        var searchQ = params.get('search') || '';
        if (searchQ) {
            var inp = document.querySelector('input[name="search"]');
            if (inp) inp.value = searchQ;
        }
        if (catId !== '1' || searchQ) {
            filterTemplates(catId, searchQ);
        }
    });
})();
</script>


<script>
// Dynamic Real-time Stats Sync
(function() {
    function refreshRealStats() {
        fetch('/api/stats')
            .then(function(r) { return r.json(); })
            .then(function(d) {
                if (!d || !d.success) return;
                var data = d.data;
                // Update elements with stat selectors or counters
                document.querySelectorAll('.stat-users, [data-stat="users"]').forEach(function(el) {
                    el.textContent = data.users_count.toLocaleString() + ' người dùng';
                });
                document.querySelectorAll('.stat-gifts, [data-stat="gifts"]').forEach(function(el) {
                    el.textContent = data.gifts_created.toLocaleString() + ' đơn hàng';
                });
                document.querySelectorAll('.stat-paid, [data-stat="paid"]').forEach(function(el) {
                    el.textContent = data.gifts_paid.toLocaleString();
                });
                // In templates.php tm-hero__stats
                var heroStatSpan = document.querySelector('.tm-hero__stats span:nth-child(2) strong');
                if (heroStatSpan) {
                    heroStatSpan.textContent = data.gifts_created.toLocaleString() + '+';
                }
            })
            .catch(function() {});
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', refreshRealStats);
    } else {
        refreshRealStats();
    }
})();
</script>

